Based on my exploration of the codebase, I understand the integration pattern. I'll implement the adaptive midpoint method using the trapezoidal implementation as a reference for the adaptive refinement pattern.

```cpp
double adaptive_midpoint(FunctionPtr f, double a, double b, double precision) {
    int N = 1;
    double h = std::abs(b - a) / N;
    double m_old = 0;
    double m_int = 0;
    int sign = (b >= a) ? 1 : -1;
    double abs_a = std::min(a, b);
    double abs_b = std::max(a, b);

    // Initial approximation with N=1
    m_int = f((abs_a + abs_b) / 2.0);

    // Adaptive refinement
    do {
        m_old = m_int;
        N *= 2;
        h = (abs_b - abs_a) / N;
        m_int = 0;

        for (int i = 0; i < N; i++) {
            double x = abs_a + (i + 0.5) * h;
            m_int += f(x);
        }
    } while (std::abs(m_int * h - m_old * h) > precision);

    return sign * m_int * h;
}
```

